    10→// ============================================================================
    11→// Part 1: 물리 메모리 관리 (Physical Memory Management)
    12→// ============================================================================
    13→
    14→/// 물리 메모리 페이지 표현
    15→pub struct PhysicalPage {
    16→    /// 페이지 번호 (0부터 시작)
    17→    pub page_number: u64,
    18→
    19→    /// 페이지 크기 (일반적으로 4KB = 4096)
    20→    pub page_size: u64,
    21→
    22→    /// 물리 주소
    23→    pub phys_addr: u64,
    24→
    25→    /// 할당 상태
    26→    pub allocated: bool,
    27→}
    28→
    29→impl PhysicalPage {
    30→    pub fn new(page_number: u64) -> Self {
    31→        PhysicalPage {
    32→            page_number,
    33→            page_size: 4096,  // 4KB 페이지
    34→            phys_addr: page_number * 4096,
    35→            allocated: false,
    36→        }
    37→    }
    38→
    39→    pub fn allocate(&mut self) {
    40→        self.allocated = true;
    41→    }
    42→
    43→    pub fn deallocate(&mut self) {
    44→        self.allocated = false;
    45→    }
    46→
    47→    pub fn is_free(&self) -> bool {
    48→        !self.allocated
    49→    }
    50→}
    51→
    52→// ============================================================================
    53→// Part 2: 페이징 시스템 (Paging System)
    54→// ============================================================================
    55→
    56→/// 페이지 테이블 항목
    57→pub struct PageTableEntry {
    58→    /// 물리 페이지 주소
    59→    pub physical_addr: u64,
    60→
    61→    /// 존재 플래그
    62→    pub present: bool,
    63→
    64→    /// 쓰기 허용 플래그
    65→    pub writable: bool,
    66→
    67→    /// 사용자 모드 접근 플래그
    68→    pub user_accessible: bool,
    69→
    70→    /// 액세스 플래그
    71→    pub accessed: bool,
    72→
    73→    /// 더티 플래그
    74→    pub dirty: bool,
    75→}
    76→
    77→impl PageTableEntry {
    78→    pub fn new(physical_addr: u64) -> Self {
    79→        PageTableEntry {
    80→            physical_addr,
    81→            present: false,
    82→            writable: false,
    83→            user_accessible: false,
    84→            accessed: false,
    85→            dirty: false,
    86→        }
    87→    }
    88→
    89→    pub fn mark_present(&mut self) {
    90→        self.present = true;
    91→    }
    92→
    93→    pub fn mark_writable(&mut self) {
    94→        self.writable = true;
    95→    }
    96→
    97→    pub fn mark_accessed(&mut self) {
    98→        self.accessed = true;
    99→    }
   100→
   101→    pub fn mark_dirty(&mut self) {
   102→        self.dirty = true;
   103→    }
   104→}
   105→
   106→/// 페이지 테이블 (1024개 항목)
   107→pub struct PageTable {
   108→    /// 페이지 테이블 항목들
   109→    pub entries: Vec<PageTableEntry>,
   110→
   111→    /// 이 테이블을 소유한 프로세스 ID
   112→    pub process_id: u32,
   113→}
   114→
   115→impl PageTable {
   116→    pub fn new(process_id: u32) -> Self {
   117→        let mut entries = Vec::new();
   118→
   119→        // 512개의 항목으로 시작
   120→        for i in 0..512 {
   121→            entries.push(PageTableEntry::new(i as u64 * 4096));
   122→        }
   123→
   124→        PageTable {
   125→            entries,
   126→            process_id,
   127→        }
   128→    }
   129→
   130→    pub fn map_page(&mut self, virtual_addr: u64, physical_addr: u64) -> bool {
   131→        let index = (virtual_addr / 4096) % 512;
   132→
   133→        if index < self.entries.len() as u64 {
   134→            let mut entry = &mut self.entries[index as usize];
   135→            entry.physical_addr = physical_addr;
   136→            entry.mark_present();
   137→            return true;
   138→        }
   139→
   140→        false
   141→    }
   142→
   143→    pub fn unmap_page(&mut self, virtual_addr: u64) -> bool {
   144→        let index = (virtual_addr / 4096) % 512;
   145→
   146→        if index < self.entries.len() as u64 {
   147→            let mut entry = &mut self.entries[index as usize];
   148→            entry.present = false;
   149→            return true;
   150→        }
   151→
   152→        false
   153→    }
   154→
   155→    pub fn translate_virtual_address(&self, virtual_addr: u64) -> Option<u64> {
   156→        let index = (virtual_addr / 4096) % 512;
   157→
   158→        if index < self.entries.len() as u64 {
   159→            let entry = &self.entries[index as usize];
   160→
   161→            if entry.present {
   162→                let offset = virtual_addr % 4096;
   163→                return Some(entry.physical_addr + offset);
   164→            }
   165→        }
   166→
   167→        None
   168→    }
   169→}
   170→
   171→// ============================================================================
   172→// Part 3: 메모리 할당자 (Memory Allocator)
   173→// ============================================================================
   174→
   175→/// 메모리 할당 정보
   176→pub struct MemoryBlock {
   177→    /// 시작 주소
   178→    pub start_addr: u64,
   179→
   180→    /// 크기 (바이트)
   181→    pub size: u64,
   182→
   183→    /// 할당 상태
   184→    pub allocated: bool,
   185→}
   186→
   187→impl MemoryBlock {
   188→    pub fn new(start_addr: u64, size: u64) -> Self {
   189→        MemoryBlock {
   190→            start_addr,
   191→            size,
   192→            allocated: false,
   193→        }
   194→    }
   195→
   196→    pub fn allocate(&mut self, requested_size: u64) -> Option<u64> {
   197→        if !self.allocated && self.size >= requested_size {
   198→            self.allocated = true;
   199→            return Some(self.start_addr);
   200→        }
   201→        None
   202→    }
   203→
   204→    pub fn deallocate(&mut self) {
   205→        self.allocated = false;
   206→    }
   207→}
   208→
   209→/// 힙 할당자
   210→pub struct HeapAllocator {
   211→    /// 메모리 블록들
   212→    pub blocks: Vec<MemoryBlock>,
   213→
   214→    /// 총 할당 가능한 크기
   215→    pub total_size: u64,
   216→
   217→    /// 할당된 크기
   218→    pub allocated_size: u64,
   219→}
   220→
   221→impl HeapAllocator {
   222→    pub fn new(start_addr: u64, total_size: u64) -> Self {
   223→        let mut blocks = Vec::new();
   224→        blocks.push(MemoryBlock::new(start_addr, total_size));
   225→
   226→        HeapAllocator {
   227→            blocks,
   228→            total_size,
   229→            allocated_size: 0,
   230→        }
   231→    }
   232→
   233→    pub fn allocate(&mut self, size: u64) -> Option<u64> {
   234→        for block in &mut self.blocks {
   235→            if let Some(addr) = block.allocate(size) {
   236→                self.allocated_size += size;
   237→                return Some(addr);
   238→            }
   239→        }
   240→        None
   241→    }
   242→
   243→    pub fn deallocate(&mut self, addr: u64) -> bool {
   244→        for block in &mut self.blocks {
   245→            if block.start_addr == addr && block.allocated {
   246→                self.allocated_size -= block.size;
   247→                block.deallocate();
   248→                return true;
   249→            }
   250→        }
   251→        false
   252→    }
   253→
   254→    pub fn fragmentation_ratio(&self) -> f64 {
   255→        if self.total_size == 0 {
   256→            return 0.0;
   257→        }
   258→
   259→        let mut free_blocks = 0;
   260→        for block in &self.blocks {
   261→            if !block.allocated {
   262→                free_blocks += 1;
   263→            }
   264→        }
   265→
   266→        (free_blocks as f64) / (self.blocks.len() as f64)
   267→    }
   268→}
   269→
   270→// ============================================================================
   271→// Part 4: 부트로더 (Bootloader)
   272→// ============================================================================
   273→
   274→/// 부트 정보
   275→pub struct BootInfo {
   276→    /// 총 물리 메모리 (MB)
   277→    pub total_memory_mb: u64,
   278→
   279→    /// 커널 로드 주소
   280→    pub kernel_load_addr: u64,
   281→
   282→    /// 커널 크기 (바이트)
   283→    pub kernel_size: u64,
   284→
   285→    /// 사용 가능한 메모리 시작 주소
   286→    pub available_memory_start: u64,
   287→
   288→    /// 사용 가능한 메모리 끝 주소
   289→    pub available_memory_end: u64,
   290→}
   291→
   292→impl BootInfo {
   293→    pub fn new() -> Self {
   294→        BootInfo {
   295→            total_memory_mb: 512,  // 512 MB 메모리 가정
   296→            kernel_load_addr: 0x100000,  // 1MB에서 시작
   297→            kernel_size: 0x100000,  // 1MB 크기
   298→            available_memory_start: 0x200000,  // 2MB부터 사용 가능
   299→            available_memory_end: 0x20000000,  // 512MB까지
   300→        }
   301→    }
   302→
   303→    pub fn total_available_memory(&self) -> u64 {
   304→        self.available_memory_end - self.available_memory_start
   305→    }
   306→}
   307→
   308→// ============================================================================
   309→// Part 5: 초기화 함수들
   310→// ============================================================================
   311→
   312→/// 부트로더 초기화
   313→pub fn init_bootloader() -> BootInfo {
   314→    println!("🔧 Initializing FreeLang OS Bootloader...");
   315→
   316→    let boot_info = BootInfo::new();
   317→    println!("✅ Boot info created:");
   318→    println!("   Total Memory: {} MB", boot_info.total_memory_mb);
   319→    println!("   Kernel Load Addr: 0x{:x}", boot_info.kernel_load_addr);
   320→    println!("   Available Memory: 0x{:x} - 0x{:x}",
   321→             boot_info.available_memory_start,
   322→             boot_info.available_memory_end);
   323→
   324→    boot_info
   325→}
   326→
   327→/// 페이징 시스템 초기화
   328→pub fn init_paging() -> PageTable {
   329→    println!("\n📄 Initializing Paging System...");
   330→
   331→    let mut page_table = PageTable::new(0);  // Kernel process ID = 0
   332→
   333→    // 커널 메모리 영역 매핑 (0x100000 ~ 0x200000)
   334→    for i in 0..256 {
   335→        let virtual_addr = 0x100000 + (i * 4096);
   336→        let physical_addr = 0x100000 + (i * 4096);
   337→        page_table.map_page(virtual_addr, physical_addr);
   338→    }
   339→
   340→    println!("✅ Paging initialized with {} page table entries", page_table.entries.len());
   341→    page_table
   342→}
   343→
   344→/// 힙 할당자 초기화
   345→pub fn init_heap_allocator(boot_info: &BootInfo) -> HeapAllocator {
   346→    println!("\n💾 Initializing Heap Allocator...");
   347→
   348→    let heap_start = boot_info.available_memory_start;
   349→    let heap_size = boot_info.total_available_memory();
   350→
   351→    let allocator = HeapAllocator::new(heap_start, heap_size);
   352→    println!("✅ Heap allocated: 0x{:x}, Size: {} MB",
   353→             heap_start, heap_size / 1024 / 1024);
   354→
   355→    allocator
   356→}
   357→
   358→// ============================================================================
   359→// Part 6: 메인 부트로더 진입점
   360→// ============================================================================
   361→
   362→pub fn main() {
   363→    println!("╔════════════════════════════════════════════════════════════╗");
   364→    println!("║     FreeLang OS Kernel - Phase G Week 1 Bootloader        ║");
   365→    println!("╚════════════════════════════════════════════════════════════╝\n");
   366→
   367→    // Step 1: 부트 정보 초기화
   368→    let boot_info = init_bootloader();
   369→
   370→    // Step 2: 페이징 시스템 초기화
   371→    let page_table = init_paging();
   372→
   373→    // Step 3: 힙 할당자 초기화
   374→    let mut heap_allocator = init_heap_allocator(&boot_info);
   375→
   376→    // Step 4: 메모리 할당 테스트
   377→    println!("\n🧪 Testing Memory Allocation...");
   378→
   379→    if let Some(addr1) = heap_allocator.allocate(4096) {
   380→        println!("✅ Allocated 4KB block at 0x{:x}", addr1);
   381→    }
   382→
   383→    if let Some(addr2) = heap_allocator.allocate(8192) {
   384→        println!("✅ Allocated 8KB block at 0x{:x}", addr2);
   385→    }
   386→
   387→    println!("   Total allocated: {} bytes", heap_allocator.allocated_size);
   388→    println!("   Fragmentation ratio: {:.2}%",
   389→             heap_allocator.fragmentation_ratio() * 100.0);
   390→
   391→    // Step 5: 가상 주소 변환 테스트
   392→    println!("\n🔍 Testing Virtual Address Translation...");
   393→
   394→    let test_vaddr = 0x100000;
   395→    if let Some(paddr) = page_table.translate_virtual_address(test_vaddr) {
   396→        println!("✅ Virtual 0x{:x} → Physical 0x{:x}", test_vaddr, paddr);
   397→    } else {
   398→        println!("❌ Translation failed for 0x{:x}", test_vaddr);
   399→    }
   400→
   401→    println!("\n✨ Bootloader initialization complete!");
   402→    println!("Ready to load kernel...\n");
   403→}
