   411→    use super::*;
   412→
   413→    #[test]
   414→    fn test_physical_page_creation() {
   415→        let page = PhysicalPage::new(0);
   416→        assert_eq!(page.page_number, 0);
   417→        assert_eq!(page.phys_addr, 0);
   418→        assert_eq!(page.is_free(), true);
   419→    }
   420→
   421→    #[test]
   422→    fn test_page_allocation() {
   423→        let mut page = PhysicalPage::new(1);
   424→        page.allocate();
   425→        assert_eq!(page.is_free(), false);
   426→        page.deallocate();
   427→        assert_eq!(page.is_free(), true);
   428→    }
   429→
   430→    #[test]
   431→    fn test_page_table_mapping() {
   432→        let mut pt = PageTable::new(0);
   433→        pt.map_page(0x1000, 0x2000);
   434→
   435→        if let Some(phys) = pt.translate_virtual_address(0x1000) {
   436→            assert_eq!(phys, 0x2000);
   437→        } else {
   438→            panic!("Virtual address translation failed");
   439→        }
   440→    }
   441→
   442→    #[test]
   443→    fn test_page_table_unmapping() {
   444→        let mut pt = PageTable::new(0);
   445→        pt.map_page(0x1000, 0x2000);
   446→        pt.unmap_page(0x1000);
   447→
   448→        assert_eq!(pt.translate_virtual_address(0x1000), None);
   449→    }
   450→
   451→    #[test]
   452→    fn test_heap_allocator() {
   453→        let mut allocator = HeapAllocator::new(0x1000, 0x10000);
   454→
   455→        if let Some(addr1) = allocator.allocate(4096) {
   456→            assert_eq!(addr1, 0x1000);
   457→            assert_eq!(allocator.allocated_size, 4096);
   458→        } else {
   459→            panic!("Allocation failed");
   460→        }
   461→    }
   462→
   463→    #[test]
   464→    fn test_heap_deallocator() {
   465→        let mut allocator = HeapAllocator::new(0x1000, 0x10000);
   466→
   467→        if let Some(addr) = allocator.allocate(4096) {
   468→            assert!(allocator.deallocate(addr));
   469→            assert_eq!(allocator.allocated_size, 0);
   470→        }
   471→    }
   472→
   473→    #[test]
   474→    fn test_boot_info() {
   475→        let boot_info = BootInfo::new();
   476→        assert_eq!(boot_info.total_memory_mb, 512);
   477→        assert!(boot_info.total_available_memory() > 0);
   478→    }
   479→}
