    63→// ============================================================================
    64→// Part 2: 프로세스 구조체
    65→// ============================================================================
    66→
    67→#[derive(Clone, Copy)]
    68→pub enum ProcessState {
    69→    Ready,
    70→    Running,
    71→    Blocked,
    72→    Terminated,
    73→}
    74→
    75→pub struct Process {
    76→    /// 프로세스 ID
    77→    pub pid: u32,
    78→
    79→    /// 프로세스 상태
    80→    pub state: ProcessState,
    81→
    82→    /// 프로그램 카운터 (PC)
    83→    pub program_counter: u64,
    84→
    85→    /// 스택 포인터 (SP)
    86→    pub stack_pointer: u64,
    87→
    88→    /// 페이지 테이블 기본 주소
    89→    pub page_table_base: u64,
    90→
    91→    /// 할당된 메모리 크기
    92→    pub memory_size: u64,
    93→
    94→    /// 프로세스 생성 시간 (ms)
    95→    pub creation_time: u64,
    96→
    97→    /// CPU 사용 시간 (ms)
    98→    pub cpu_time: u64,
    99→}
   100→
   101→impl Process {
   102→    pub fn new(pid: u32, program_counter: u64, stack_pointer: u64) -> Self {
   103→        Process {
   104→            pid,
   105→            state: ProcessState::Ready,
   106→            program_counter,
   107→            stack_pointer,
   108→            page_table_base: 0,
   109→            memory_size: 0,
   110→            creation_time: 0,
   111→            cpu_time: 0,
   112→        }
   113→    }
   114→
   115→    pub fn mark_running(&mut self) {
   116→        self.state = ProcessState::Running;
   117→    }
   118→
   119→    pub fn mark_blocked(&mut self) {
   120→        self.state = ProcessState::Blocked;
   121→    }
   122→
   123→    pub fn mark_ready(&mut self) {
   124→        self.state = ProcessState::Ready;
   125→    }
   126→
   127→    pub fn mark_terminated(&mut self) {
   128→        self.state = ProcessState::Terminated;
   129→    }
   130→
   131→    pub fn is_runnable(&self) -> bool {
   132→        match self.state {
   133→            ProcessState::Ready | ProcessState::Running => true,
   134→            _ => false,
   135→        }
   136→    }
   137→}
