   140→// Part 3: 인터럽트 핸들러
   141→// ============================================================================
   142→
   143→pub enum InterruptType {
   144→    Timer,           // 타이머 인터럽트
   145→    PageFault,       // 페이지 폴트
   146→    SegmentationFault, // 세그멘테이션 폴트
   147→    DivideByZero,    // 0으로 나누기
   148→    InvalidOp,       // 잘못된 명령어
   149→}
   150→
   151→pub struct InterruptHandler {
   152→    /// 인터럽트 타입
   153→    pub interrupt_type: InterruptType,
   154→
   155→    /// 인터럽트 발생 주소
   156→    pub address: u64,
   157→
   158→    /// 인터럽트 발생 시간 (ms)
   159→    pub timestamp: u64,
   160→}
   161→
   162→impl InterruptHandler {
   163→    pub fn new(interrupt_type: InterruptType, address: u64, timestamp: u64) -> Self {
   164→        InterruptHandler {
   165→            interrupt_type,
   166→            address,
   167→            timestamp,
   168→        }
   169→    }
   170→
   171→    pub fn handle(&self) -> String {
   172→        match self.interrupt_type {
   173→            InterruptType::Timer => {
   174→                format!("⏱️  Timer interrupt at 0x{:x}", self.address)
   175→            }
   176→            InterruptType::PageFault => {
   177→                format!("📄 Page fault at 0x{:x}", self.address)
   178→            }
   179→            InterruptType::SegmentationFault => {
   180→                format!("💥 Segmentation fault at 0x{:x}", self.address)
   181→            }
   182→            InterruptType::DivideByZero => {
   183→                format!("➗ Divide by zero at 0x{:x}", self.address)
   184→            }
   185→            InterruptType::InvalidOp => {
   186→                format!("⚠️  Invalid operation at 0x{:x}", self.address)
   187→            }
   188→        }
   189→    }
   190→}
