   250→
   251→pub struct Kernel {
   252→    /// 메모리 관리자
   253→    pub memory_manager: KernelMemoryManager,
   254→
   255→    /// 프로세스 목록
   256→    pub processes: Vec<Process>,
   257→
   258→    /// 다음 프로세스 ID
   259→    pub next_pid: u32,
   260→
   261→    /// 현재 실행 중인 프로세스
   262→    pub current_process_id: Option<u32>,
   263→
   264→    /// 인터럽트 카운트
   265→    pub interrupt_count: u32,
   266→
   267→    /// 시스템 호출 카운트
   268→    pub syscall_count: u32,
   269→
   270→    /// 커널 부팅 시간 (ms)
   271→    pub boot_time: u64,
   272→}
   273→
   274→impl Kernel {
   275→    pub fn new() -> Self {
   276→        Kernel {
   277→            memory_manager: KernelMemoryManager::new(0x200000, 0x1FE00000),
   278→            processes: Vec::new(),
   279→            next_pid: 1,
   280→            current_process_id: None,
   281→            interrupt_count: 0,
   282→            syscall_count: 0,
   283→            boot_time: 0,
   284→        }
   285→    }
   286→
   287→    pub fn create_process(&mut self, program_counter: u64) -> u32 {
   288→        let pid = self.next_pid;
   289→        let stack_pointer = 0x7FFFFFFF;  // 스택은 위에서 아래로
   290→
   291→        let mut process = Process::new(pid, program_counter, stack_pointer);
   292→        process.memory_size = 4096;  // 각 프로세스는 4KB 메모리
   293→        process.page_table_base = pid as u64 * 0x1000;
   294→
   295→        self.processes.push(process);
   296→        self.next_pid += 1;
   297→
   298→        println!("✨ Process {} created at PC=0x{:x}", pid, program_counter);
   299→        pid
   300→    }
   301→
   302→    pub fn terminate_process(&mut self, pid: u32) -> bool {
   303→        for process in &mut self.processes {
   304→            if process.pid == pid {
   305→                process.mark_terminated();
   306→                return true;
   307→            }
   308→        }
   309→        false
   310→    }
   311→
   312→    pub fn get_process(&self, pid: u32) -> Option<&Process> {
   313→        self.processes.iter().find(|p| p.pid == pid)
   314→    }
   315→
   316→    pub fn get_process_mut(&mut self, pid: u32) -> Option<&mut Process> {
   317→        self.processes.iter_mut().find(|p| p.pid == pid)
   318→    }
   319→
   320→    pub fn process_count(&self) -> usize {
   321→        self.processes.len()
   322→    }
   323→
   324→    pub fn runnable_process_count(&self) -> usize {
   325→        self.processes.iter().filter(|p| p.is_runnable()).count()
   326→    }
   327→
   328→    pub fn print_status(&self) {
   329→        println!("\n╔════════════════════════════════════════════════════════════╗");
   330→        println!("║             FreeLang OS Kernel Status Report               ║");
   331→        println!("╚════════════════════════════════════════════════════════════╝");
   332→
   333→        println!("\n📊 Memory Status:");
   334→        println!("   Heap Start: 0x{:x}", self.memory_manager.heap_start);
   335→        println!("   Used: {} bytes", self.memory_manager.used_size);
   336→        println!("   Available: {} bytes", self.memory_manager.available_memory());
   337→        println!("   Usage: {:.2}%", self.memory_manager.memory_usage_percent());
   338→
   339→        println!("\n🔄 Process Status:");
   340→        println!("   Total Processes: {}", self.process_count());
   341→        println!("   Runnable Processes: {}", self.runnable_process_count());
   342→        println!("   Current Process ID: {:?}", self.current_process_id);
   343→
   344→        println!("\n⚡ Interrupt Status:");
   345→        println!("   Total Interrupts: {}", self.interrupt_count);
   346→        println!("   Total Syscalls: {}", self.syscall_count);
   347→
   348→        if self.process_count() > 0 {
   349→            println!("\n📋 Process List:");
   350→            for process in &self.processes {
   351→                println!("   PID {} - State: {:?}, PC: 0x{:x}",
   352→                         process.pid,
   353→                         process.state,
   354→                         process.program_counter);
   355→            }
   356→        }
   357→
   358→        println!();
   359→    }
   360→}
