    13→
    14→/// 인터럽트 타입 (x86-64 표준)
    15→#[derive(Clone, Copy, Debug)]
    16→pub enum InterruptType {
    17→    /// 0: Divide Error (정수 0으로 나누기)
    18→    DivideError,
    19→
    20→    /// 1: Debug Exception
    21→    Debug,
    22→
    23→    /// 2: Non-Maskable Interrupt
    24→    NMI,
    25→
    26→    /// 3: Breakpoint
    27→    Breakpoint,
    28→
    29→    /// 4: Overflow
    30→    Overflow,
    31→
    32→    /// 5: Bound Range Exceeded
    33→    BoundRangeExceeded,
    34→
    35→    /// 6: Invalid Opcode
    36→    InvalidOpcode,
    37→
    38→    /// 7: Device Not Available
    39→    DeviceNotAvailable,
    40→
    41→    /// 8: Double Fault
    42→    DoubleFault,
    43→
    44→    /// 10: Invalid TSS (Task State Segment)
    45→    InvalidTSS,
    46→
    47→    /// 11: Segment Not Present
    48→    SegmentNotPresent,
    49→
    50→    /// 12: Stack Segment Fault
    51→    StackSegmentFault,
    52→
    53→    /// 13: General Protection Fault
    54→    GeneralProtectionFault,
    55→
    56→    /// 14: Page Fault
    57→    PageFault,
    58→
    59→    /// 16: Floating-Point Exception
    60→    FloatingPointException,
    61→
    62→    /// 17: Alignment Check
    63→    AlignmentCheck,
    64→
    65→    /// 18: Machine Check
    66→    MachineCheck,
    67→
    68→    /// 19: SIMD Floating-Point Exception
    69→    SIMDException,
    70→
    71→    /// Hardware Interrupt (IRQ)
    72→    HardwareInterrupt { irq: u8 },
    73→
    74→    /// Software Interrupt / System Call
    75→    SystemCall,
    76→}
    77→
    78→impl InterruptType {
    79→    pub fn to_vector(&self) -> u8 {
    80→        match self {
    81→            InterruptType::DivideError => 0,
    82→            InterruptType::Debug => 1,
    83→            InterruptType::NMI => 2,
    84→            InterruptType::Breakpoint => 3,
    85→            InterruptType::Overflow => 4,
    86→            InterruptType::BoundRangeExceeded => 5,
    87→            InterruptType::InvalidOpcode => 6,
    88→            InterruptType::DeviceNotAvailable => 7,
    89→            InterruptType::DoubleFault => 8,
    90→            InterruptType::InvalidTSS => 10,
    91→            InterruptType::SegmentNotPresent => 11,
    92→            InterruptType::StackSegmentFault => 12,
    93→            InterruptType::GeneralProtectionFault => 13,
    94→            InterruptType::PageFault => 14,
    95→            InterruptType::FloatingPointException => 16,
    96→            InterruptType::AlignmentCheck => 17,
    97→            InterruptType::MachineCheck => 18,
    98→            InterruptType::SIMDException => 19,
    99→            InterruptType::HardwareInterrupt { irq } => 32 + irq,
   100→            InterruptType::SystemCall => 128,
   101→        }
   102→    }
   103→
   104→    pub fn is_exception(&self) -> bool {
   105→        match self {
   106→            InterruptType::HardwareInterrupt { .. } => false,
   107→            InterruptType::SystemCall => false,
   108→            _ => true,
   109→        }
   110→    }
   111→
   112→    pub fn is_fault(&self) -> bool {
   113→        matches!(self,
   114→            InterruptType::DivideError |
   115→            InterruptType::InvalidOpcode |
   116→            InterruptType::PageFault |
   117→            InterruptType::GeneralProtectionFault
   118→        )
   119→    }
   120→
   121→    pub fn description(&self) -> &'static str {
   122→        match self {
   123→            InterruptType::DivideError => "Divide by zero",
   124→            InterruptType::Debug => "Debug breakpoint",
   125→            InterruptType::NMI => "Non-maskable interrupt",
   126→            InterruptType::Breakpoint => "Breakpoint",
   127→            InterruptType::Overflow => "Integer overflow",
   128→            InterruptType::BoundRangeExceeded => "Bound range exceeded",
   129→            InterruptType::InvalidOpcode => "Invalid opcode",
   130→            InterruptType::DeviceNotAvailable => "Device not available",
   131→            InterruptType::DoubleFault => "Double fault",
   132→            InterruptType::InvalidTSS => "Invalid TSS",
   133→            InterruptType::SegmentNotPresent => "Segment not present",
   134→            InterruptType::StackSegmentFault => "Stack segment fault",
   135→            InterruptType::GeneralProtectionFault => "General protection fault",
   136→            InterruptType::PageFault => "Page fault",
   137→            InterruptType::FloatingPointException => "Floating-point exception",
   138→            InterruptType::AlignmentCheck => "Alignment check",
   139→            InterruptType::MachineCheck => "Machine check",
   140→            InterruptType::SIMDException => "SIMD exception",
   141→            InterruptType::HardwareInterrupt { .. } => "Hardware interrupt",
   142→            InterruptType::SystemCall => "System call",
   143→        }
   144→    }
   145→}
