   387→// Part 5: 인터럽트 핸들러
   388→// ============================================================================
   389→
   390→pub struct InterruptHandler {
   391→    /// 처리한 인터럽트 수
   392→    pub handled_count: u64,
   393→
   394→    /// 처리 불가능한 인터럽트 수
   395→    pub unhandled_count: u64,
   396→
   397→    /// 마지막 인터럽트 프레임
   398→    pub last_frame: Option<InterruptFrame>,
   399→
   400→    /// 인터럽트 통계
   401→    pub statistics: Vec<(u8, u64)>,  // (vector, count)
   402→}
   403→
   404→impl InterruptHandler {
   405→    pub fn new() -> Self {
   406→        InterruptHandler {
   407→            handled_count: 0,
   408→            unhandled_count: 0,
   409→            last_frame: None,
   410→            statistics: vec![],
   411→        }
   412→    }
   413→
   414→    pub fn handle_interrupt(&mut self, int_type: InterruptType, mut frame: InterruptFrame) -> Result<(), String> {
   415→        frame.timestamp = self.handled_count as u32;
   416→        frame.occurrence_count = self.handled_count as u32;
   417→
   418→        let vector = int_type.to_vector();
   419→
   420→        // 통계 업데이트
   421→        let mut found = false;
   422→        for (v, count) in &mut self.statistics {
   423→            if *v == vector {
   424→                *count += 1;
   425→                found = true;
   426→                break;
   427→            }
   428→        }
   429→        if !found {
   430→            self.statistics.push((vector, 1));
   431→        }
   432→
   433→        self.last_frame = Some(frame);
   434→
   435→        match int_type {
   436→            InterruptType::DivideError => {
   437→                println!("💥 EXCEPTION: Divide by zero at 0x{:x}",
   438→                         self.last_frame.as_ref().unwrap().rip);
   439→                Err("Divide by zero".to_string())
   440→            },
   441→            InterruptType::PageFault => {
   442→                println!("📄 EXCEPTION: Page fault at 0x{:x}",
   443→                         self.last_frame.as_ref().unwrap().rip);
   444→                Err("Page fault".to_string())
   445→            },
   446→            InterruptType::GeneralProtectionFault => {
   447→                println!("⚠️  EXCEPTION: General protection fault");
   448→                Err("GPF".to_string())
   449→            },
   450→            InterruptType::HardwareInterrupt { irq } => {
   451→                println!("⚡ Hardware interrupt: IRQ {}", irq);
   452→                self.handled_count += 1;
   453→                Ok(())
   454→            },
   455→            InterruptType::SystemCall => {
   456→                println!("🔗 System call from 0x{:x}",
   457→                         self.last_frame.as_ref().unwrap().rip);
   458→                self.handled_count += 1;
   459→                Ok(())
   460→            },
   461→            _ => {
   462→                println!("⚡ Interrupt: {}", int_type.description());
   463→                self.handled_count += 1;
   464→                Ok(())
   465→            }
   466→        }
   467→    }
   468→
   469→    pub fn print_statistics(&self) {
   470→        println!("\n📊 Interrupt Handler Statistics:");
   471→        println!("  Handled: {}", self.handled_count);
   472→        println!("  Unhandled: {}", self.unhandled_count);
   473→
   474→        if !self.statistics.is_empty() {
   475→            println!("\n  Per-Interrupt Counts:");
   476→            for (vector, count) in &self.statistics {
   477→                println!("    Vector {}: {} occurrences", vector, count);
   478→            }
   479→        }
   480→    }
   481→}
