   131→/// 프로세스의 완전한 CPU 상태 (컨텍스트)
   132→pub struct ProcessContext {
   133→    /// 일반 목적 레지스터
   134→    pub registers: GeneralPurposeRegisters,
   135→
   136→    /// 프로그램 카운터 (RIP)
   137→    pub instruction_pointer: u64,
   138→
   139→    /// CPU 플래그
   140→    pub flags: CPUFlags,
   141→
   142→    /// 컨텍스트 ID (고유 식별자)
   143→    pub context_id: u32,
   144→
   145→    /// 컨텍스트 생성 시간
   146→    pub created_at: u64,
   147→
   148→    /// 컨텍스트 전환 횟수
   149→    pub switch_count: u32,
   150→}
   151→
   152→impl ProcessContext {
   153→    pub fn new(context_id: u32, instruction_pointer: u64, stack_addr: u64) -> Self {
   154→        ProcessContext {
   155→            registers: GeneralPurposeRegisters::initialize_for_process(stack_addr),
   156→            instruction_pointer,
   157→            flags: CPUFlags::new(),
   158→            context_id,
   159→            created_at: 0,
   160→            switch_count: 0,
   161→        }
   162→    }
   163→
   164→    pub fn save_state(&mut self, rax: u64, rbx: u64, rcx: u64, rdx: u64,
   165→                      rsi: u64, rdi: u64, rbp: u64, rsp: u64) {
   166→        self.registers.rax = rax;
   167→        self.registers.rbx = rbx;
   168→        self.registers.rcx = rcx;
   169→        self.registers.rdx = rdx;
   170→        self.registers.rsi = rsi;
   171→        self.registers.rdi = rdi;
   172→        self.registers.rbp = rbp;
   173→        self.registers.rsp = rsp;
   174→    }
   175→
   176→    pub fn restore_state(&self) -> [u64; 8] {
   177→        self.registers.get_all_registers()
   178→    }
   179→
   180→    pub fn record_switch(&mut self) {
   181→        self.switch_count += 1;
   182→    }
   183→
   184→    pub fn print_context(&self) {
   185→        println!("\n📋 Process Context #{}:", self.context_id);
   186→        println!("  RIP (Instruction Pointer): 0x{:016x}", self.instruction_pointer);
   187→        println!("  Flags: {:?}", self.flags.to_u64());
   188→        println!("  Context Switches: {}", self.switch_count);
   189→        println!("  Registers:");
   190→        self.registers.print_registers();
   191→    }
   192→}
