   463→            sign: self.sign,
   464→            overflow: self.overflow,
   465→            interrupt_enable: self.interrupt_enable,
   466→        }
   467→    }
   468→}
   469→
   470→impl Clone for ProcessContext {
   471→    fn clone(&self) -> Self {
